  "claim_id": "C018",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C018.component",
    "value": "The proposed causal signal is a reduction in missing approval attachments after responsibility becomes explicit, repeated across comparable observation periods if order volume permits.",
    "scope": "An anticipated signal specification, not an observed outcome; repetition is conditional on volume.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the reduction, its temporal relationship to explicit responsibility, comparable observation periods and the volume qualification."
    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "Where attachment responsibility is unclear, assign explicit responsibility prospectively and compare missing-attachment frequency before and after the change across comparable covered orders using the same predefined inspection interval. A subsequent reduction, repeated if volume permits, constitutes the proposed signal; temporal association alone does not exclude alternative causes.",
    "scope": "Prospective attachment outcomes under the specified comparison; a causal signal rather than conclusive causal identification.",
